import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CCCdsIgc.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function l(h,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="为什么有的操作要我确认-有的不用" tabindex="-1">为什么有的操作要我确认，有的不用？ <a class="header-anchor" href="#为什么有的操作要我确认-有的不用" aria-label="Permalink to &quot;为什么有的操作要我确认，有的不用？&quot;">​</a></h2><p>按操作的影响分级：查看、搜索、在工作区里生成文件直接做；认不出的命令问一次，可以选「以后自动执行」；删除、覆盖、改系统设置这类每次都问。详见 <a href="/help/guide/safety.html">确认与安全</a>。</p><h2 id="ai-把文件改坏了怎么办" tabindex="-1">AI 把文件改坏了怎么办？ <a class="header-anchor" href="#ai-把文件改坏了怎么办" aria-label="Permalink to &quot;AI 把文件改坏了怎么办？&quot;">​</a></h2><p>回答下面点「改动了 N 个文件」，可以逐个对比、一键还原到这一轮之前。删除的文件在回收站里。</p><h2 id="程序关了-做到一半的任务还在吗" tabindex="-1">程序关了，做到一半的任务还在吗？ <a class="header-anchor" href="#程序关了-做到一半的任务还在吗" aria-label="Permalink to &quot;程序关了，做到一半的任务还在吗？&quot;">​</a></h2><p>在。任务每一步都会存下来，重新打开后点「接着做」。详见 <a href="/help/guide/tasks.html">长任务与定时任务</a>。</p><h2 id="定时任务没有执行" tabindex="-1">定时任务没有执行？ <a class="header-anchor" href="#定时任务没有执行" aria-label="Permalink to &quot;定时任务没有执行？&quot;">​</a></h2><p>FlyknitBuddy 要开着（收在托盘里就行）。关机期间错过的任务，开机后补跑最近一次，超过 12 小时就跳过。</p><h2 id="提示「今天的额度已用完」" tabindex="-1">提示「今天的额度已用完」？ <a class="header-anchor" href="#提示「今天的额度已用完」" aria-label="Permalink to &quot;提示「今天的额度已用完」？&quot;">​</a></h2><p>公司给每台电脑设了每日用量上限，第二天自动恢复。急用请联系 IT 调整。</p><h2 id="我的对话记录存在哪里-会被别人看到吗" tabindex="-1">我的对话记录存在哪里？会被别人看到吗？ <a class="header-anchor" href="#我的对话记录存在哪里-会被别人看到吗" aria-label="Permalink to &quot;我的对话记录存在哪里？会被别人看到吗？&quot;">​</a></h2><p>对话记录和记忆存在你自己电脑的 <code>%APPDATA%\\Flyknit</code> 里。公司服务器会记录 AI 执行过的操作（审计），只有被授权的管理员能查看，查看会留下访问记录。</p><h2 id="命令行里敲-flyknit-提示找不到" tabindex="-1">命令行里敲 flyknit 提示找不到？ <a class="header-anchor" href="#命令行里敲-flyknit-提示找不到" aria-label="Permalink to &quot;命令行里敲 flyknit 提示找不到？&quot;">​</a></h2><ul><li>需要 IT 打开「命令行 / IDE 接入」，并用新版安装程序安装（安装时会加入 PATH）；</li><li>PATH 只对<strong>新开的</strong>命令行窗口生效，关掉重开一个；</li><li>也可以直接写完整路径：<code>&quot;C:\\Program Files\\FlyknitBuddy\\flyknit.exe&quot;</code>。</li></ul><h2 id="命令行输出的中文是乱码" tabindex="-1">命令行输出的中文是乱码？ <a class="header-anchor" href="#命令行输出的中文是乱码" aria-label="Permalink to &quot;命令行输出的中文是乱码？&quot;">​</a></h2><p>请升级到最新版。新版在命令行窗口里显示时会自动切换到 UTF-8；输出给脚本读取时 JSON 里的中文写成 <code>\\uXXXX</code>，<code>ConvertFrom-Json</code> 读出来就是原文。</p><h2 id="怎么反馈问题" tabindex="-1">怎么反馈问题？ <a class="header-anchor" href="#怎么反馈问题" aria-label="Permalink to &quot;怎么反馈问题？&quot;">​</a></h2><p>「设置 → 意见反馈」，可以附截图和日志包，IT 在后台处理。</p>',19)])])}const p=e(i,[["render",l]]);export{f as __pageData,p as default};
